from .service import stream_rows

def take(resource, transform, limit):
    if limit <= 0:
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    finally:
        # Closing a generator that already finished (exhausted or failed) is a no-op,
        # so the resource is closed exactly once on every path.
        stream.close()
    return result

