def _close_after_error(resource):
    # Runs while an iteration or transform error is propagating. A cleanup
    # failure must not replace that original error, so it is discarded here.
    try:
        resource.close()
    except Exception:
        pass


def stream_rows(resource, transform):
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit close() or garbage collection: no error is active, so a
        # cleanup failure propagates to the caller of close().
        resource.close()
        raise
    except BaseException:
        # Read or transform error (or an error thrown in at the yield point):
        # keep it as the active error.
        _close_after_error(resource)
        raise
    else:
        # Exhausted: no error is active, so a cleanup failure propagates.
        resource.close()
